{"summary": "已重写 lib/plan.mjs 并去掉代码中所有转义字符（换行改用 String.fromCharCode(10) 常量 NL），node --check 通过，自检命令实测输出 trae 1 / codebuddy 1 / 合计 2 个任务 / codebuddy。", "code": "/
 * lib/plan.mjs —— 批次预演（dry-run）：不调用任何 agent，先算出「这批会怎么分、要多久、有没有坑」

 * 自检命令（仓库根目录直接跑）：
 * node --check lib/plan.mjs
 * node -e "import('./lib/plan.mjs').then(m=>{console.log(m.renderPlan(m.plan([{id:1,text:'写个函数'},{id:2,text:'讲讲TCP'}])));console.log(m.routeOf('实现接口','auto'))})"
 * 期望输出：表格里 trae 1 个、codebuddy 1 个，合计 2 个任务；末行 codebuddy
 /

/ 默认单次耗时：取各 agent 的实测均值，供 ETA 估算；可被 opts.avgMs 覆盖做校准 /
const DEFAULT_AVG_MS = { trae: 27000, codebuddy: 85000, workbuddy: 19000 };

/* 默认并发：trae 只有单个 Agent 页面，codebuddy 是独立子进程可以多开 /
const DEFAULT_SLOTS = { trae: 1, codebuddy: 6, workbuddy: 1 };

/* 已知 agent 的稳定顺序，保证 perAgent 与表格输出每次一致 /
const AGENTS = ['trae', 'codebuddy', 'workbuddy'];

/* 动作词：出现即说明想要「产出代码」，而不是「解释概念」 /
const ACTION_WORDS = ['写', '实现', '重构', '修复', '优化', '生成', '编写', '改造', '新增'];

/* 产物词：和动作词同句出现时基本可以判定为有判据的代码活 /
const PRODUCT_WORDS = ['函数', '类', '接口', '模块', '脚本', '命令', 'sql', '正则', '测试', '代码', '组件', 'api', '程序', '算法'];

/* 文本超过这个长度就不属于短问答，需要看是否含工程词 /
const SHORT_TEXT_CHARS = 800;

/* 单任务文本超过这个长度时，单轮上下文可能装不下 /
const LONG_TASK_CHARS = 6000;

/* 预计墙钟超过这个值就提醒用户落盘后离开 /
const WALL_WARN_MS = 15 * 60 * 1000;

/* 一个 agent 的波次超过 slots 的这个倍数，说明排队太深，应该拆批 /
const WAVE_WARN_MULT = 3;

/* 换行符常量：代码里不写转义字符，拼接与解析统一用它 */
const NL = String.fromCharCode(10);

/
 * 判断文本是否是「有判据的代码活」：同一句里同时出现动作词和产物词。
 * 之所以要求同句，是因为「解释一下这个函数的实现原理」里也有这两个词，
 * 但它要的是散文；先按行、再按标点分句，能把这类误判挡掉。
 * @param {string} text 任务文本
 * @returns {boolean} true 表示应交给代码型 agent
 */
const hasCodeIntent = (text) => {
  const lower = String(text || '').toLowerCase();
  return lower.split(NL).some((line) =>
    line.split(/[。！？!?；;]/).some((sentence) => {
      const hasAction = ACTION_WORDS.some((word) => sentence.includes(word));
      const hasProduct = PRODUCT_WORDS.some((word) => sentence.includes(word));
      return hasAction && hasProduct;
    }),
  );
};

/
 * 判定单条任务该给谁。
 * 判定顺序是「先看代码意图，再看长度，最后看工程词」：
 * 代码意图最可靠（有动作加产物就是要交付物）；短文本用 trae 更快（19-36s 对 54-118s）；
 * 长文本已不适合 trae 单轮，只要还在谈工程就给 codebuddy。
 * @param {string} text 任务文本
 * @param {'auto'|'trae'|'codebuddy'} [mode] 显式指定时不走自动判定
 * @returns {'trae'|'codebuddy'} 目标 agent
 */
export const routeOf = (text, mode = 'auto') => {
  if (mode === 'trae' || mode === 'codebuddy') return mode;
  const raw = String(text || '');
  if (hasCodeIntent(raw)) return 'codebuddy';
  if (raw.length <= SHORT_TEXT_CHARS) return 'trae';
  const lower = raw.toLowerCase();
  const hasEngineering = [...ACTION_WORDS, ...PRODUCT_WORDS].some((word) => lower.includes(word));
  return hasEngineering ? 'codebuddy' : 'trae';
};

/
 * 把毫秒格式化成给人看的时长。
 * 之所以分档：ETA 小于 1 分钟时用秒更有感觉，超过就换成分钟，避免出现 0.0min。
 * @param {number} ms 毫秒
 * @returns {string} 形如 27.0s 或 3.6min
 */
const fmtMs = (ms) => {
  const value = Number(ms) || 0;
  if (value < 60000) return ${(value / 1000).toFixed(1)}s;
  return ${(value / 60000).toFixed(1)}min;
};

/
 * 预演一次批处理分配，纯函数：不读文件、不发请求、不写状态。
 * 之所以要在真跑之前算：一次 codebuddy 调用 54-118s，跑错分配浪费的是分钟级时间，
 * 而预演成本是微秒级；同时把「超出会话上限」「排队太深」这类问题提前暴露。
 * @param {Array<{id: number|string, text: string}>} tasks 待执行任务
 * @param {object} [opts] 选项
 * @param {'auto'|'trae'|'codebuddy'} [opts.mode] 强制指定 agent，auto 表示按文本判定
 * @param {object|number} [opts.slots] 并发数，对象按 agent 指定，数字表示所有 agent 同值
 * @param {number} [opts.traeSoftLimit] trae 单会话软上限，超出改派 codebuddy
 * @param {object} [opts.avgMs] 覆盖默认单次耗时，用于用实测值校准 ETA
 * @returns {{allocations: Array<{id: number|string, agent: string, movedFrom?: string}>, perAgent: object, etaMs: number, warnings: string[]}}
 */
export const plan = (tasks, opts = {}) => {
  const list = Array.isArray(tasks) ? tasks : [];
  const mode = opts.mode || 'auto';
  const avgMs = { ...DEFAULT_AVG_MS, ...(opts.avgMs || {}) };
  const slots = { ...DEFAULT_SLOTS };
  if (typeof opts.slots === 'number') {
    for (const agent of AGENTS) slots[agent] = opts.slots;
  } else if (opts.slots && typeof opts.slots === 'object') {
    Object.assign(slots, opts.slots);
  }
  const traeSoftLimit = Number.isFinite(opts.traeSoftLimit) ? opts.traeSoftLimit : 8;

  const allocations = list.map((task) => ({ id: task.id, agent: routeOf(task.text, mode) }));
  const traeBefore = allocations.filter((item) => item.agent === 'trae').length;

  // trae 只有单会话，超过软上限的部分从尾部改派 codebuddy，
  // 并记下 movedFrom 让上层能解释「为什么这条被换人做了」。
  if (traeBefore > traeSoftLimit) {
    let remain = traeBefore;
    for (let index = allocations.length - 1; index >= 0 && remain > traeSoftLimit; index -= 1) {
      const item = allocations[index];
      if (item.agent !== 'trae') continue;
      item.agent = 'codebuddy';
      item.movedFrom = 'trae';
      remain -= 1;
    }
  }

  const perAgent = {};
  for (const agent of AGENTS) {
    const count = allocations.filter((item) => item.agent === agent).length;
    if (count === 0) continue;
    const slot = slots[agent] || 1;
    const waves = Math.ceil(count / slot);
    perAgent[agent] = { count, slots: slot, waves, etaMs: waves * (avgMs[agent] || 0) };
  }

  // 各 agent 并行推进，整批墙钟由最慢的那个决定
  const etaMs = Object.values(perAgent).reduce((max, item) => Math.max(max, item.etaMs), 0);

  const warnings = [];
  if (traeBefore > traeSoftLimit) {
    warnings.push(trae 会话上限 ${traeSoftLimit}，超出的 ${traeBefore - traeSoftLimit} 个会改派给 codebuddy);
  }
  const buddy = perAgent.codebuddy;
  if (buddy && buddy.count > buddy.slots * WAVE_WARN_MULT) {
    warnings.push(codebuddy 需要 ${buddy.waves} 波，建议拆批);
  }
  list.forEach((task, index) => {
    const chars = String(task.text || '').length;
    if (chars > LONG_TASK_CHARS) {
      warnings.push(第 ${index + 1} 个任务文本 ${chars} 字符，可能超单轮窗口);
    }
  });
  if (etaMs > WALL_WARN_MS) {
    warnings.push(预计 ${(etaMs / 60000).toFixed(0)} 分钟，建议用 --out 落盘后离开);
  }

  return { allocations, perAgent, etaMs, warnings };
};

/
 * 把 plan 结果渲染成对齐文本，方便直接贴到终端或 PR 评论。
 * 之所以自己拼表格而不是用第三方表格库：项目零依赖，且这里只需 5 列定宽；
 * 表头刻意用 ASCII，避免中文宽度导致 padEnd 对不齐。
 * @param {object} planResult plan() 的返回值
 * @returns {string} 多行文本（不含末尾换行）
 */
export const renderPlan = (planResult) => {
  const { perAgent = {}, etaMs = 0, warnings = [] } = planResult || {};
  const lines = [];
  lines.push('agent'.padEnd(12) + 'tasks'.padStart(6) + 'slots'.padStart(7) + 'waves'.padStart(7) + 'eta'.padStart(9));
  lines.push('-'.repeat(12) + '-'.repeat(6) + '-'.repeat(7) + '-'.repeat(7) + '-'.repeat(9));
  let total = 0;
  for (const agent of AGENTS) {
    const item = perAgent[agent];
    if (!item) continue;
    total += item.count;
    lines.push(
      agent.padEnd(12) +
        String(item.count).padStart(6) +
        String(item.slots).padStart(7) +
        String(item.waves).padStart(7) +
        fmtMs(item.etaMs).padStart(9),
    );
  }
  for (const warning of warnings) lines.push(! ${warning});
  lines.push(合计 ${total} 个任务，预计墙钟 ${fmtMs(etaMs)}（由并行最慢的 agent 决定）);
  return lines.join(NL);
};
